mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[0.42,0.32,0.23,0.52,0.25]","0.23,0.25,0.32,0.42,0.52"),
        ("[0.9,0.1]","0.1,0.9"),
        ("[0.9,0.1,0.5]","0.1,0.5,0.9"),
        ("[0.2,0.2,0.1]","0.1,0.2,0.2"),
        ("[0.01,0.99]","0.01,0.99"),
        ("  \n[0.42,0.32,0.23,0.52,0.25]\n  ","0.23,0.25,0.32,0.42,0.52"),
        ("\n[0.01,0.99]\n","0.01,0.99")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bucket-sort");
}
